def condense_whitespace(s):
    result = []
    prev_space = False
    for c in s:
        if c.isspace():
            if not prev_space:
                result.append(' ')
            prev_space = True
        else:
            result.append(c)
            prev_space = False
    return "".join(result).strip()

def remove_duplicate_adjacent_chars(s):
    if not s:
        return ""
    result = [s[0]]
    for c in s[1:]:
        if c != result[-1]:
            result.append(c)
    return "".join(result)

def alternate_upper_lower(s):
    result = []
    letter_idx = 0
    for c in s:
        if c.isalpha():
            result.append(c.upper() if letter_idx % 2 == 0 else c.lower())
            letter_idx += 1
        else:
            result.append(c)
    return "".join(result)

def toggle_case_at_indices(s, indices):
    idx_set = set(indices)
    result = []
    for i, c in enumerate(s):
        if i in idx_set:
            result.append(c.swapcase())
        else:
            result.append(c)
    return "".join(result)

def capitalize_after_delimiter(s, delim):
    result = list(s)
    capitalize_next = False
    for i, c in enumerate(result):
        if capitalize_next and c.isalpha():
            result[i] = c.upper()
            capitalize_next = False
        if c == delim:
            capitalize_next = True
    return "".join(result)

def is_alternating_case(s):
    letters = [c for c in s if c.isalpha()]
    for i in range(1, len(letters)):
        if letters[i].isupper() == letters[i - 1].isupper():
            return False
    return True

def is_alternating_parity_digits(s):
    for i in range(1, len(s)):
        if (int(s[i]) % 2) == (int(s[i - 1]) % 2):
            return False
    return True

def merge_alternately(a, b):
    result = []
    i = 0
    while i < len(a) or i < len(b):
        if i < len(a):
            result.append(a[i])
        if i < len(b):
            result.append(b[i])
        i += 1
    return "".join(result)

def has_alternating_vowel_consonant(s):
    vowels = set("aeiouAEIOU")
    letters = [c for c in s if c.isalpha()]
    for i in range(1, len(letters)):
        prev_v = letters[i - 1] in vowels
        cur_v = letters[i] in vowels
        if prev_v == cur_v:
            return False
    return True

def compress_runs_min_length(s, min_run):
    if not s:
        return ""
    result = []
    i = 0
    n = len(s)
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        run_len = j - i
        if run_len >= min_run:
            result.append(s[i] + str(run_len))
        else:
            result.append(s[i] * run_len)
        i = j
    return "".join(result)

def compress_to_tuples(s):
    if not s:
        return []
    result = []
    prev = s[0]
    count = 1
    for c in s[1:]:
        if c == prev:
            count += 1
        else:
            result.append((prev, count))
            prev = c
            count = 1
    result.append((prev, count))
    return result

def count_runs(s):
    if not s:
        return 0
    count = 1
    for i in range(1, len(s)):
        if s[i] != s[i - 1]:
            count += 1
    return count

def longest_run(s):
    if not s:
        return ("", 0)
    best_char, best_len = s[0], 1
    cur_char, cur_len = s[0], 1
    for c in s[1:]:
        if c == cur_char:
            cur_len += 1
        else:
            cur_char, cur_len = c, 1
        if cur_len > best_len:
            best_char, best_len = cur_char, cur_len
    return (best_char, best_len)

def split_on_multiple_delimiters(s, delims):
    delim_set = set(delims)
    tokens = []
    current = []
    for c in s:
        if c in delim_set:
            if current:
                tokens.append("".join(current))
                current = []
        else:
            current.append(c)
    if current:
        tokens.append("".join(current))
    return tokens

def tokenize_camel_case(s):
    if not s:
        return []
    words = []
    current = s[0]
    for c in s[1:]:
        if c.isupper():
            words.append(current)
            current = c
        else:
            current += c
    words.append(current)
    return words

def tokenize_mixed_alnum(s):
    tokens = []
    current = ""
    current_type = None
    for c in s:
        if c.isalpha():
            ctype = 'alpha'
        elif c.isdigit():
            ctype = 'digit'
        else:
            ctype = None
        if ctype is None:
            if current:
                tokens.append(current)
                current = ""
                current_type = None
            continue
        if ctype == current_type:
            current += c
        else:
            if current:
                tokens.append(current)
            current = c
            current_type = ctype
    if current:
        tokens.append(current)
    return tokens
